#include <bits/stdc++.h>
using namespace std;

vector<uint16_t> input_split() {
    string buf;
    getline(cin, buf);
    stringstream ss(buf);
    vector<uint16_t> v;
    uint16_t x;
    while (ss >> x) {
        v.push_back(x);
    }
    return v;
}

optional<uint16_t> determine_b(const vector<uint16_t>& v) {
    uint32_t sum = 0;
    for (auto x : v) sum += x;
    if (sum % 5 == 0 && sum != 0) {
        return static_cast<uint16_t>(sum / 5);
    } else {
        return nullopt;
    }
}

void print_res(optional<uint16_t> res) {
    if (res.has_value()) {
        cout << res.value();
    } else {
        cout << "-1";
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    print_res(determine_b(input_split()));
    return 0;
}

